                    chunk = os.read(fd, 65536)
                except OSError:
                    return
                if not chunk:
                    return
                buf += chunk
                if b"\x1b]11;?" in chunk:
                    os.write(fd, b"\x1b]11;rgb:1e1e/1e1e/1e1e\x07")
    def send_slow(s, delay=0.1):
        for ch in s:
            os.write(fd, ch.encode('latin1'))
            drain(delay)
    def send(s):
        os.write(fd, s.encode('latin1'))
    def clean():
        text = buf.decode('utf-8', errors='replace')
        ansi = re.compile(r'(\x1b\[[0-9;?]*[a-zA-Z])|(\x1b\][^\x07\x1b]*(\x07|\x1b\\))|(\x1b[()][A-Z0-9])')
        return ansi.sub('', text)

    drain(6.0)
    for target, tag in [(":images", "images"), (":networks", "networks"), (":volumes", "volumes")]:
        send_slow(target)
        send("\r")
        drain(2.0)
        c = clean()
        lines = [l for l in c.split('\n') if l.strip()]
        with open(f"/tmp/view_{tag}.txt","w") as f:
            f.write("\n".join(lines[-40:]))
        buf = b""
    try:
        os.kill(pid, 15)
    except ProcessLookupError:
        pass
